const TOL: f64 = 1.0e-13;

fn assert_grid_close(actual: &[[CcComplex; 4]; 4], expected: &[[[f64; 2]; 4]; 4], label: &str) {
    for r in 0..4 {
        for c in 0..4 {
            for axis in 0..2 {
                let delta = (actual[r][c][axis] - expected[r][c][axis]).abs();
                assert!(
                    delta < TOL,
                    "{label}[{r}][{c}].{axis} off by {delta:e}: got {got:e}, oracle {want:e}",
                    got = actual[r][c][axis],
                    want = expected[r][c][axis],
                );
            }
        }
    }
}

#[test]
fn lambda_matches_pr08_stam_closed_form_and_published_values() {
    for (n, expected) in [
        (3, CC_RING_LAMBDA_N3),
        (5, CC_RING_LAMBDA_N5),
        (6, CC_RING_LAMBDA_N6),
        (7, CC_RING_LAMBDA_N7),
        (8, CC_RING_LAMBDA_N8),
    ] {
        let lambda = cc_subdominant_lambda(n).unwrap();
        assert!(
            (lambda - expected).abs() < TOL,
            "lambda mismatch at n={n}: {lambda:e} vs {expected:e}",
        );
        // Strict subdominance window from PR08 eq (6.7)-(6.8).
        assert!(lambda > 0.25 && lambda < 1.0);
    }
    assert!((cc_subdominant_lambda(4).unwrap() - 0.5).abs() < TOL);
    assert!(cc_subdominant_lambda(2).is_err());
    assert!(cc_characteristic_ring(2).is_err());
}

#[test]
fn extended_net_is_a_lambda_eigenvector_of_the_level0_matrix() {
    for n in [3, 4, 5, 6, 7, 8, 10, 12] {
        let ring = cc_characteristic_ring(n).unwrap();
        let a = cc_level0_subdivision_rows(n);
        for (r, row) in a.iter().enumerate() {
            for axis in 0..2 {
                let image: f64 = row
                    .iter()
                    .zip(&ring.extended_net)
                    .map(|(w, v)| w * v[axis])
                    .sum();
                let target = ring.lambda * ring.extended_net[r][axis];
                assert!(
                    (image - target).abs() < TOL,
                    "A·C != λ·C at n={n} row={r} axis={axis}: {image:e} vs {target:e}",
                );
            }
        }
    }
}

#[test]
fn subdivision_rows_are_affine_and_refined_star_scales_by_lambda() {
    for n in [3, 4, 5, 6, 7, 8, 10] {
        let a_bar = cc_extended_subdivision_rows(n);
        assert_eq!(a_bar.len(), cc_refined_net_len(n));
        for (r, row) in a_bar.iter().enumerate() {
            let sum: f64 = row.iter().sum();
            assert!(
                (sum - 1.0).abs() < TOL,
                "Ā row {r} at n={n} sums to {sum} (must be affine)",
            );
        }
        // Rows 1..2n+8 of Ā are the level-0 matrix A, so the refined
        // net's first 2n+8 entries must be exactly λ·C.
        let ring = cc_characteristic_ring(n).unwrap();
        for (r, value) in ring
            .refined_net
            .iter()
            .take(cc_extended_net_len(n))
            .enumerate()
        {
            for axis in 0..2 {
                let target = ring.lambda * ring.extended_net[r][axis];
                assert!(
                    (value[axis] - target).abs() < TOL,
                    "refined net entry {r} at n={n} is not λ·C",
                );
            }
        }
    }
}

#[test]
fn picked_grids_share_overlapping_control_points_exactly() {
    // Adjacent subpatches share 12 control points of one B-spline net:
    // Ω₁ v-rows 1..3 = Ω₂ v-rows 0..2, and Ω₂ u-cols 0..2 = Ω₃
    // u-cols 1..3. Exact label identities, so exact equality holds and
    // the three ring patches join C² by construction.
    for n in [3, 4, 5, 6, 7, 8, 10, 12] {
        let ring = cc_characteristic_ring(n).unwrap();
        let [q1, q2, q3] = &ring.grids;
        for r in 0..3 {
            for c in 0..4 {
                assert_eq!(q1[r + 1][c], q2[r][c], "Ω₁/Ω₂ overlap at n={n}");
            }
        }
        for r in 0..4 {
            for c in 0..3 {
                assert_eq!(q2[r][c], q3[r][c + 1], "Ω₂/Ω₃ overlap at n={n}");
            }
        }
    }
}

#[test]
fn picking_after_one_more_subdivision_scales_grids_by_lambda() {
    // Self-similarity of the characteristic spline: χ(s/2) = λ·χ(s).
    // Subdividing the (eigenvector) net once more and re-picking must
    // reproduce λ × the level-1 grids.
    for n in [3, 5, 6, 7, 8] {
        let ring = cc_characteristic_ring(n).unwrap();
        let a = cc_level0_subdivision_rows(n);
        let level1_net: Vec<CcComplex> = a
            .iter()
            .map(|row| {
                let mut acc = [0.0_f64; 2];
                for (w, v) in row.iter().zip(&ring.extended_net) {
                    acc[0] += w * v[0];
                    acc[1] += w * v[1];
                }
                acc
            })
            .collect();
        let a_bar = cc_extended_subdivision_rows(n);
        let level2_net: Vec<CcComplex> = a_bar
            .iter()
            .map(|row| {
                let mut acc = [0.0_f64; 2];
                for (w, v) in row.iter().zip(&level1_net) {
                    acc[0] += w * v[0];
                    acc[1] += w * v[1];
                }
                acc
            })
            .collect();
        let picks = cc_picking_vectors(n);
        for (grid, pick) in ring.grids.iter().zip(&picks) {
            for (m, &label) in pick.iter().enumerate() {
                let level2 = level2_net[label - 1];
                let expected = grid[m / 4][m % 4];
                for axis in 0..2 {
                    assert!(
                        (level2[axis] - ring.lambda * expected[axis]).abs() < TOL,
                        "level-2 grid is not λ × level-1 at n={n}",
                    );
                }
            }
        }
    }
}

#[test]
fn valence_four_grids_form_an_affine_lattice() {
    // n = 4 is the regular case: λ = 1/2 and the characteristic map is
    // the identity, so every picked B-spline grid must be an affine
    // lattice (all second differences vanish).
    let ring = cc_characteristic_ring(4).unwrap();
    for grid in &ring.grids {
        for axis in 0..2 {
            for r in 0..4 {
                for c in 0..2 {
                    let second =
                        grid[r][c][axis] - 2.0 * grid[r][c + 1][axis] + grid[r][c + 2][axis];
                    assert!(second.abs() < TOL, "u second difference at n=4");
                }
            }
            for c in 0..4 {
                for r in 0..2 {
                    let second =
                        grid[r][c][axis] - 2.0 * grid[r + 1][c][axis] + grid[r + 2][c][axis];
                    assert!(second.abs() < TOL, "v second difference at n=4");
                }
            }
        }
    }
}

#[test]
fn grids_and_normalization_match_the_python_oracle() {
    let n3 = cc_characteristic_ring(3).unwrap();
    assert_grid_close(&n3.grids[1], &CC_RING_GRID_Q2_N3, "n3 q2");
    for axis in 0..2 {
        assert!((n3.f110[axis] - CC_RING_F110_N3[axis]).abs() < TOL);
    }

    let n5 = cc_characteristic_ring(5).unwrap();
    assert_grid_close(&n5.grids[0], &CC_RING_GRID_Q1_N5, "n5 q1");
    assert_grid_close(&n5.grids[1], &CC_RING_GRID_Q2_N5, "n5 q2");
    assert_grid_close(&n5.grids[2], &CC_RING_GRID_Q3_N5, "n5 q3");
    for axis in 0..2 {
        assert!((n5.f110[axis] - CC_RING_F110_N5[axis]).abs() < TOL);
    }

    for (n, f110) in [
        (6, CC_RING_F110_N6),
        (7, CC_RING_F110_N7),
        (8, CC_RING_F110_N8),
    ] {
        let ring = cc_characteristic_ring(n).unwrap();
        for axis in 0..2 {
            assert!(
                (ring.f110[axis] - f110[axis]).abs() < TOL,
                "f(1,1,0) mismatch at n={n}",
            );
        }
    }
}

#[test]
fn rotating_the_seed_by_one_sector_rotates_the_grids() {
    // Rotational covariance: the construction is linear and the seed
    // is frequency-one, so multiplying the seed phase by e^{2πi/n}
    // must multiply every picked grid entry by the same rotation.
    let n = 5;
    let ring = cc_characteristic_ring(n).unwrap();
    let alpha = core::f64::consts::TAU / n as f64;
    let rot = [alpha.cos(), alpha.sin()];
    let a_bar = cc_extended_subdivision_rows(n);
    let rotated_extended: Vec<CcComplex> = ring
        .extended_net
        .iter()
        .map(|v| [v[0] * rot[0] - v[1] * rot[1], v[0] * rot[1] + v[1] * rot[0]])
        .collect();
    let rotated_refined: Vec<CcComplex> = a_bar
        .iter()
        .map(|row| {
            let mut acc = [0.0_f64; 2];
            for (w, v) in row.iter().zip(&rotated_extended) {
                acc[0] += w * v[0];
                acc[1] += w * v[1];
            }
            acc
        })
        .collect();
    let picks = cc_picking_vectors(n);
    for (grid, pick) in ring.grids.iter().zip(&picks) {
        for (m, &label) in pick.iter().enumerate() {
            let expected = grid[m / 4][m % 4];
            let expected = [
                expected[0] * rot[0] - expected[1] * rot[1],
                expected[0] * rot[1] + expected[1] * rot[0],
            ];
            let actual = rotated_refined[label - 1];
            for axis in 0..2 {
                assert!((actual[axis] - expected[axis]).abs() < TOL);
            }
        }
    }
}
